"""Generated by Riffle from a 2-qubit circuit."""
from guppylang import guppy
from guppylang.std.quantum import qubit, measure, discard, cz, h, x
from guppylang.std.builtins import result


@guppy
def main() -> None:
    q0 = qubit(); q1 = qubit()
    h(q0)  # s0
    h(q1)  # s1
    cz(q0, q1)  # oracle
    h(q0)  # h0
    h(q1)  # h1
    x(q0)  # x0
    x(q1)  # x1
    cz(q0, q1)  # mirror
    x(q0)  # u0
    x(q1)  # u1
    h(q0)  # out0
    h(q1)  # out1
    result("c0", measure(q0).read())
    result("c1", measure(q1).read())
